const allItems = $input.all();

const sections = {
  Lang1: { services: [], faq: [], objections: [], script: [], disclaimer: [] },
  Lang2: { services: [], faq: [], objections: [], script: [], disclaimer: [] }
};

for (const item of allItems) {
  const { pageContent, namespace, metadata } = item.json;
  const lang = (metadata && metadata.language ? metadata.language : 'Lang1');
  const relevant = ['services', 'faq', 'objections', 'script', 'disclaimer'];
  if (!relevant.includes(namespace)) continue;
  if (sections[lang] && sections[lang][namespace] !== undefined) {
    const clean = pageContent.replace(/^\[(?:Lang1|Lang2)\]\s*/, '').trim();
    if (clean.length > 5) sections[lang][namespace].push(clean);
  }
}

const hdrs = {
  services: '# COMPANY SERVICES DESCRIPTION',
  faq: '# FREQUENTLY ASKED QUESTIONS (FAQ)',
  objections: '# OBJECTION HANDLING',
  script: '# QUALIFICATION SCRIPT',
  disclaimer: '# DISCLAIMER'
};

function buildFile(lang) {
  const parts = [];
  for (const [sec, hdr] of Object.entries(hdrs)) {
    const content = sections[lang][sec];
    if (content.length > 0) {
      parts.push(hdr);
      parts.push('');
      parts.push(content.join('\n\n'));
      parts.push('');
    }
  }
  return parts.join('\n');
}

const lang1Text = buildFile('Lang1');
const lang2Text = buildFile('Lang2');

console.log('Vapi KB: Lang1 ' + lang1Text.length + ' chars, Lang2 ' + lang2Text.length + ' chars');

return [
  {
    json: {
      lang: 'Lang1',
      fileName: 'KB_Lang1.txt',
      fileContent: lang1Text,
      assistantId: 'YOUR_VAPI_ASSISTANT_ID_LANG1',
      oldFileId: '', // leave empty on first run, fill in after first sync
      kbName: 'company_kb_lang1',
      kbDescription: 'Your company knowledge base, language 1. FAQ, services, prices, objections.'
    }
  },
  {
    json: {
      lang: 'Lang2',
      fileName: 'KB_Lang2.txt',
      fileContent: lang2Text,
      assistantId: 'YOUR_VAPI_ASSISTANT_ID_LANG2',
      oldFileId: '', // leave empty on first run, fill in after first sync
      kbName: 'company_kb_lang2',
      kbDescription: 'Your company knowledge base, language 2. FAQ, services, prices, objections.'
    }
  }
];

// Get fileContent from the KB-building node, not the previous node
const buildNode = $('Generate KB Files').all();

const results = [];

for (const item of buildNode) {
  const { lang, fileName, fileContent, assistantId, kbName, kbDescription } = item.json;

  if (!fileContent) throw new Error('fileContent is empty for ' + lang);

  const base64Content = Buffer.from(fileContent, 'utf-8').toString('base64');

  results.push({
    json: { lang, fileName, assistantId, kbName, kbDescription },
    binary: {
      data: {
        data: base64Content,
        mimeType: 'text/plain',
        fileName: fileName,
        fileExtension: 'txt'
      }
    }
  });
}

return results;

// Process all items (Lang 1 and Lang 2)
const uploadItems = $input.all();
const prepItems = $('Prepare KB File for Upload').all();

const results = [];

for (let i = 0; i < uploadItems.length; i++) {
  const uploadResp = uploadItems[i].json;
  const newFileId = uploadResp.id;

  if (!newFileId) throw new Error('Vapi returned no file_id for item ' + i + ': ' + JSON.stringify(uploadResp));

  // Match the corresponding prep item by index
  const prep = prepItems[i] ? prepItems[i].json : prepItems[0].json;

  results.push({ json: {
    lang: prep.lang,
    newFileId,
    assistantId: prep.assistantId,
    kbName: prep.kbName,
    kbDescription: prep.kbDescription
  }});
}

return results;

// Process all items (Lang 1 and Lang 2)
const assistantItems = $input.all();
const toolItems = $('Create Query Tool in Vapi').all();
const fileItems = $('Extract KB File ID').all();

const results = [];

for (let i = 0; i < assistantItems.length; i++) {
  const assistantData = assistantItems[i].json;
  const toolResp = toolItems[i] ? toolItems[i].json : toolItems[0].json;
  const fileNode = fileItems[i] ? fileItems[i].json : fileItems[0].json;

  const toolId = toolResp.id;
  if (!toolId) throw new Error('Query Tool not created for ' + fileNode.lang + ': ' + JSON.stringify(toolResp));

  const currentModel = assistantData.model || {};

  // REPLACE all tools with the new one — do not accumulate
  const newToolIds = [toolId];

  results.push({ json: {
    lang: fileNode.lang,
    assistantId: fileNode.assistantId,
    toolId,
    newFileId: fileNode.newFileId,
    patchBody: JSON.stringify({ 
      model: Object.assign({}, currentModel, { toolIds: newToolIds }) 
    })
  }});
}

return results;

// Log all items (Lang 1 and Lang 2)
const patchItems = $('Prepare Assistant Update Payload').all();
const resultItems = $input.all();

const results = [];

for (let i = 0; i < resultItems.length; i++) {
  const result = resultItems[i].json;
  const prev = patchItems[i] ? patchItems[i].json : patchItems[0].json;
  const ok = !!result.id;

  console.log('Vapi KB Sync [' + prev.lang + ']: ' + (ok ? 'OK' : 'ERROR'));

  results.push({ json: {
    status: ok ? 'success' : 'error',
    lang: prev.lang,
    assistantId: prev.assistantId,
    newFileId: prev.newFileId,
    toolId: prev.toolId,
    timestamp: new Date().toISOString()
  }});
}

return results;

const allItems = [];

for (const item of $input.all()) {
  const j = item.json;

  const lang = j.property_language || 'Lang1';
  const nodeSource = item.pairedItem?.sourceNode || '';

  const namespaceMap = {
    'Notion: Services':            'services',
    'Notion: FAQ':                 'faq',
    'Notion: Qualification Script':'script',
    'Notion: Dialogue Tree':       'dialog',
    'Notion: Objection Handling':  'objections',
    'Notion: Disclaimers':         'disclaimer',
    'Notion: Call Log':            'calls',
  };

  let namespace = 'services';
  for (const [key, val] of Object.entries(namespaceMap)) {
    if (nodeSource.includes(key)) { namespace = val; break; }
  }

  const parts = [
    j.property_content,
    j.property_section,
    j.property_subsection,
    j.property_question,
    j.property_answer,
    j.property_category,
    j.property_objection,
    j.property_bot_response,
    j.property_objection_type,
  ].filter(v => v && v.trim().length > 2);

  const pageContent = `[${lang}] ` + parts.join(' | ').trim();

  allItems.push({
    json: {
      pageContent,
      namespace,
      metadata: {
        source:    j.property_section || j.property_category || namespace,
        namespace,
        language:  lang,
        notionId:  j.id || '',
        updatedAt: j.last_edited_time || new Date().toISOString()
      }
    }
  });
}

if (allItems.length === 0) {
  return [{ json: { status: 'no_updates', count: 0 } }];
}

console.log(`Prepared records: ${allItems.length}`);
return allItems;

const items = $input.all();
console.log(`Pinecone sync: ${items.length} vectors written`);
return [{ json: { status: 'success', vectorsWritten: items.length, timestamp: new Date().toISOString() } }];
